                    </div>
                    <div class="m-col">
                        <div class="m-card is-alt"><div class="m-between"><span class="m-label">Room 101 <span class="m-pin">4</span></span><span class="hc-badge hc-badge-success">Active</span></div><div class="m-small" style="margin-top:.2rem;">Start · 8:00 AM</div></div>
                        <div class="m-card"><div class="m-label">Current</div><div class="m-bold">CFD-2026-0007</div><div class="m-timer" style="font-size:.9rem;color:var(--hc-success)">12:41</div></div>
                        <div class="m-card"><div class="m-label">Next</div><div class="m-bold">CFD-2026-0012</div><div class="m-small m-muted">Expected 9:20 AM</div></div>
